steps.solution:
// Lines that start with // are notes for people. The app skips them.
script "First drive" for racing v1

// racing-standard sees nine distance rays, its speed and the angle to the road.
brain racing-standard

// How sharply the road bends 40 m ahead. A tight right bend reads 0, a straight 0.5 and a tight left bend 1.
sensor bendFar "Bend 40 m ahead" in -0.05 1/m .. 0.05 1/m = track.curvatureAhead(distance: 40 m)

// How much tire slide is fine before it costs points. 0 is full grip, 1 is a full slide.
let slipLimit = 0.3

// This block runs for every car, 30 times per second of driving.
each tick {
  // Steer and press the pedal exactly as the brain says.
  drive(steer: brain.steer, pedal: brain.pedal)

  // A tiny reward for speed, every tick, so faster cars score higher.
  reward +0.002 * car.speed
  // One point each time the car passes a checkpoint. They sit every 10 m along the road.
  reward +1 when checkpoint.passed
  // Ten points for every lap the car finishes.
  reward +10 when lap.completed
  // Sliding means the car asked the tires for more grip than they have.
  reward -0.05 when car.slip > slipLimit

  // Crossing the white edge line ends this car's run.
  stop "crash" when car.offTrack
  // A car that has not moved forward for 5 seconds is stuck, so stop it too.
  stop "stalled" when car.noProgress > 5 s
}

// This block runs once per generation, after every car has stopped.
each generation {
  // Train on the Hairpin: a long straight, then a tight bend.
  useTrack(id: "hairpin")
}
